<?php
require 'config.php'; require_login();
$user=current_user(); $role=$user['role']; $message=''; $error='';
$vehicleTypes=['Ambulance','Van','SUV','Pickup','Other municipal vehicle'];
function make_ref(){return 'MVR-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));}
$profileStmt=$conn->prepare('SELECT valid_id_type,valid_id_path,valid_id_back_path,birth_certificate_path,death_certificate_path,id_verified FROM users WHERE id=?');$profileStmt->bind_param('i',$user['id']);$profileStmt->execute();$identity=$profileStmt->get_result()->fetch_assoc();
$idTypes=requester_id_types();if(!empty($identity['valid_id_type'])&&!array_key_exists($identity['valid_id_type'],$idTypes))$idTypes[$identity['valid_id_type']]=$identity['valid_id_type'];
$uploadedDocuments=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();
 $action=$_POST['action']??'';
 try {
  if($action==='create' && $role==='requester'){
   $purpose=trim($_POST['purpose']??'');$dest=trim($_POST['destination']??'');$type=trim($_POST['vehicle_type']??'');$pass=max(1,(int)($_POST['passenger_count']??1));$depTs=strtotime($_POST['departure_at']??'');$retTs=strtotime($_POST['return_at']??'');$em=isset($_POST['is_emergency'])?1:0;
   if(!$purpose||!$dest||!$type||!$depTs||!$retTs||$retTs<=$depTs) throw new Exception('Complete all fields and ensure return time is after departure.');
   if($depTs<time()-300) throw new Exception('Departure time cannot be in the past.');
   if(!in_array($type,$vehicleTypes,true)) throw new Exception('Select a valid vehicle type.');
   $dep=date('Y-m-d H:i:s',$depTs);$ret=date('Y-m-d H:i:s',$retTs);
   $validIdType=trim($_POST['valid_id_type']??'');if(!array_key_exists($validIdType,requester_id_types())&&$validIdType!==$identity['valid_id_type'])throw new Exception('Select a valid ID type.');
   $validIdUpload=store_requester_document($_FILES['valid_id']??[]);if($validIdUpload)$uploadedDocuments[]=$validIdUpload;
   $validIdBackUpload=store_requester_document($_FILES['valid_id_back']??[]);if($validIdBackUpload)$uploadedDocuments[]=$validIdBackUpload;
   $birthUpload=store_requester_document($_FILES['birth_certificate']??[]);if($birthUpload)$uploadedDocuments[]=$birthUpload;
   $deathUpload=store_requester_document($_FILES['death_certificate']??[]);if($deathUpload)$uploadedDocuments[]=$deathUpload;
   $validIdPath=$validIdUpload?:$identity['valid_id_path'];$validIdBackPath=$validIdBackUpload?:$identity['valid_id_back_path'];$birthPath=$birthUpload?:null;$deathPath=$deathUpload?:null;
   if(!$validIdPath||!$validIdBackPath)throw new Exception('Upload both the front and back of a valid ID before submitting a vehicle request.');
   if($validIdType!==$identity['valid_id_type']&&(!$validIdUpload||!$validIdBackUpload))throw new Exception('Upload both sides of the ID when changing its type.');
   $conn->begin_transaction();
   $verified=($validIdUpload||$validIdBackUpload)?0:(int)$identity['id_verified'];
   $upd=$conn->prepare('UPDATE users SET valid_id_type=?,valid_id_path=?,valid_id_back_path=?,birth_certificate_path=COALESCE(?,birth_certificate_path),death_certificate_path=COALESCE(?,death_certificate_path),id_verified=? WHERE id=?');$upd->bind_param('sssssii',$validIdType,$validIdPath,$validIdBackPath,$birthPath,$deathPath,$verified,$user['id']);$upd->execute();
   $ref=make_ref();$stmt=$conn->prepare('INSERT INTO reservations(reference_no,requester_id,requester_id_verified,purpose,destination,vehicle_type,passenger_count,departure_at,return_at,is_emergency) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->bind_param('siisssissi',$ref,$user['id'],$verified,$purpose,$dest,$type,$pass,$dep,$ret,$em);$stmt->execute();$id=$conn->insert_id;log_activity($conn,$id,'Request submitted',$ref.' submitted for '.$dest);$conn->commit();go('reservations.php?id='.$id.'&created=1');
  }
  $id=(int)($_POST['id']??0);$stmt=$conn->prepare('SELECT r.*,u.valid_id_type,u.valid_id_path,u.valid_id_back_path,u.birth_certificate_path,u.death_certificate_path,u.id_verified FROM reservations r JOIN users u ON u.id=r.requester_id WHERE r.id=?');$stmt->bind_param('i',$id);$stmt->execute();$res=$stmt->get_result()->fetch_assoc();if(!$res)throw new Exception('Reservation not found.');
  if($role==='requester' && $res['requester_id']==$user['id'] && $action==='cancel' && $res['status']==='Pending Admin Review'){
   $u=$conn->prepare("UPDATE reservations SET status='Cancelled' WHERE id=? AND status='Pending Admin Review'");$u->bind_param('i',$id);$u->execute();log_activity($conn,$id,'Request cancelled',$res['reference_no']);go('reservations.php');
  } elseif($role==='admin' && $action==='admin_review' && $res['status']==='Pending Admin Review'){
   $note=trim($_POST['note']??'');$decision=$_POST['decision']??'forward';
   if($decision==='reject'){$s='Rejected';$stmt=$conn->prepare('UPDATE reservations SET status=?,admin_note=? WHERE id=?');$stmt->bind_param('ssi',$s,$note,$id);}else{if(empty($res['id_verified'])&&(empty($res['valid_id_path'])||empty($res['valid_id_back_path'])||empty($_POST['verify_requester_id'])))throw new Exception('Review both sides of the requester ID and confirm the requester before forwarding.');$s='Pending Secretary Approval';$stmt=$conn->prepare('UPDATE reservations SET status=?,admin_note=?,requester_id_verified=1 WHERE id=?');$stmt->bind_param('ssi',$s,$note,$id);$mark=$conn->prepare('UPDATE users SET id_verified=1 WHERE id=?');$mark->bind_param('i',$res['requester_id']);$mark->execute();}
   $stmt->execute();log_activity($conn,$id,'Admin review',$decision.' · '.$note);go('reservations.php?id='.$id);
  } elseif($role==='secretary' && $action==='secretary_review' && $res['status']==='Pending Secretary Approval'){
   $note=trim($_POST['note']??'');$decision=$_POST['decision']??'approve';$s=$decision==='approve'?'Approved':'Rejected';$approver=$user['id'];$stmt=$conn->prepare('UPDATE reservations SET status=?,secretary_note=?,approved_by=? WHERE id=?');$stmt->bind_param('ssii',$s,$note,$approver,$id);$stmt->execute();log_activity($conn,$id,'Secretary decision',$s.' · '.$note);go('reservations.php?id='.$id);
  } elseif($role==='gso' && $action==='assign' && $res['status']==='Approved'){
   $vid=(int)($_POST['vehicle_id']??0);$did=(int)($_POST['driver_id']??0);
   $vq=$conn->prepare('SELECT capacity,status FROM vehicles WHERE id=?');$vq->bind_param('i',$vid);$vq->execute();$veh=$vq->get_result()->fetch_assoc();
   $dq=$conn->prepare('SELECT status FROM drivers WHERE id=?');$dq->bind_param('i',$did);$dq->execute();$drv=$dq->get_result()->fetch_assoc();
   if(!$veh||!$drv)throw new Exception('Select a valid vehicle and driver.');
   if(in_array($veh['status'],['Maintenance','Inactive'],true))throw new Exception('That vehicle is not available for assignment.');
   if($drv['status']==='Unavailable')throw new Exception('That driver is marked unavailable.');
   if((int)$veh['capacity']<(int)$res['passenger_count'])throw new Exception('That vehicle seats '.(int)$veh['capacity'].' but this request has '.(int)$res['passenger_count'].' passengers.');
   $chk=$conn->prepare("SELECT COUNT(*) c FROM reservations WHERE status IN ('Assigned','Dispatched') AND (vehicle_id=? OR driver_id=?) AND id<>? AND departure_at < ? AND return_at > ?");$chk->bind_param('iiiss',$vid,$did,$id,$res['return_at'],$res['departure_at']);$chk->execute();if((int)$chk->get_result()->fetch_assoc()['c']>0)throw new Exception('That vehicle or driver overlaps with another active reservation.');
   // Vehicle/driver status flips to In Use / Assigned at dispatch, not here, so a future booking doesn't block the fleet today.
   $s='Assigned';$stmt=$conn->prepare('UPDATE reservations SET vehicle_id=?,driver_id=?,status=? WHERE id=?');$stmt->bind_param('iisi',$vid,$did,$s,$id);$stmt->execute();
   log_activity($conn,$id,'Vehicle and driver assigned','Vehicle #'.$vid.', driver #'.$did);go('reservations.php?id='.$id);
  } elseif($role==='gso' && $action==='dispatch' && $res['status']==='Assigned'){
   $out=(float)($_POST['odometer_out']??0);$fuel=trim($_POST['fuel_out']??'');
   if(!$res['vehicle_id']||!$res['driver_id'])throw new Exception('Assign a vehicle and driver before dispatching.');
   if($fuel==='')throw new Exception('Enter the fuel level.');
   $now=date('Y-m-d H:i:s');$s='Dispatched';
   $conn->begin_transaction();
   $stmt=$conn->prepare('UPDATE reservations SET status=?,dispatched_at=?,odometer_out=?,fuel_out=? WHERE id=?');$stmt->bind_param('ssdsi',$s,$now,$out,$fuel,$id);$stmt->execute();
   $vid=(int)$res['vehicle_id'];$u=$conn->prepare("UPDATE vehicles SET status='In Use' WHERE id=?");$u->bind_param('i',$vid);$u->execute();
   $did=(int)$res['driver_id'];$u=$conn->prepare("UPDATE drivers SET status='Assigned' WHERE id=?");$u->bind_param('i',$did);$u->execute();
   log_activity($conn,$id,'Vehicle dispatched','Odometer '.$out.', fuel '.$fuel);
   $conn->commit();go('reservations.php?id='.$id);
  } elseif($role==='gso' && $action==='return' && $res['status']==='Dispatched'){
   $in=(float)($_POST['odometer_in']??0);$fuel=trim($_POST['fuel_in']??'');$condition=trim($_POST['return_condition']??'');
   if($in<(float)$res['odometer_out'])throw new Exception('Return odometer cannot be lower than dispatch odometer.');
   if($fuel===''||$condition==='')throw new Exception('Enter the fuel level and vehicle condition.');
   $now=date('Y-m-d H:i:s');$s='Returned';
   $conn->begin_transaction();
   $stmt=$conn->prepare('UPDATE reservations SET status=?,returned_at=?,odometer_in=?,fuel_in=?,return_condition=? WHERE id=?');$stmt->bind_param('ssdssi',$s,$now,$in,$fuel,$condition,$id);$stmt->execute();
   // Free the vehicle/driver only if no other trip is still out with them (and never override Maintenance/Inactive/Unavailable).
   if($res['vehicle_id']){$vid=(int)$res['vehicle_id'];$u=$conn->prepare("UPDATE vehicles SET status='Available' WHERE id=? AND status='In Use' AND NOT EXISTS (SELECT 1 FROM reservations x WHERE x.vehicle_id=? AND x.status='Dispatched' AND x.id<>?)");$u->bind_param('iii',$vid,$vid,$id);$u->execute();}
   if($res['driver_id']){$did=(int)$res['driver_id'];$u=$conn->prepare("UPDATE drivers SET status='Available' WHERE id=? AND status='Assigned' AND NOT EXISTS (SELECT 1 FROM reservations x WHERE x.driver_id=? AND x.status='Dispatched' AND x.id<>?)");$u->bind_param('iii',$did,$did,$id);$u->execute();}
   log_activity($conn,$id,'Vehicle returned','Odometer '.$in.', condition '.$condition);
   $conn->commit();go('reservations.php?id='.$id);
  } else throw new Exception('This action is not available for your role or this reservation status.');
 } catch(mysqli_sql_exception $e){$conn->rollback();foreach($uploadedDocuments as $document)@unlink(__DIR__.'/private_uploads/'.$document);error_log($e->getMessage());$error='A database error occurred. Please try again.';}
 catch(Throwable $e){$conn->rollback();foreach($uploadedDocuments as $document)@unlink(__DIR__.'/private_uploads/'.$document);$error=$e->getMessage();}
}
$selected=(int)($_GET['id']??0);$detail=null;
if($selected){$stmt=$conn->prepare('SELECT r.*,u.full_name requester_name,u.email requester_email,u.address requester_address,u.contact_number requester_contact,u.valid_id_type,u.valid_id_path,u.valid_id_back_path,u.birth_certificate_path,u.death_certificate_path,u.id_verified,v.vehicle_name,v.plate_number,d.full_name driver_name FROM reservations r JOIN users u ON r.requester_id=u.id LEFT JOIN vehicles v ON r.vehicle_id=v.id LEFT JOIN drivers d ON r.driver_id=d.id WHERE r.id=?');$stmt->bind_param('i',$selected);$stmt->execute();$detail=$stmt->get_result()->fetch_assoc();if($detail && $role==='requester' && $detail['requester_id']!=$user['id'])$detail=null;if($detail && $role==='secretary' && $detail['status']==='Pending Admin Review')$detail=null;}
if($detail && $role!=='requester'){$requesterHistory=$conn->prepare('SELECT id,reference_no,status,created_at FROM reservations WHERE requester_id=? AND id<>? ORDER BY created_at DESC LIMIT 5');$requesterHistory->bind_param('ii',$detail['requester_id'],$detail['id']);$requesterHistory->execute();$requesterHistoryRows=$requesterHistory->get_result();}
if($role==='requester'){$stmt=$conn->prepare('SELECT r.*,v.vehicle_name,d.full_name driver_name FROM reservations r LEFT JOIN vehicles v ON r.vehicle_id=v.id LEFT JOIN drivers d ON r.driver_id=d.id WHERE r.requester_id=? ORDER BY r.created_at DESC');$stmt->bind_param('i',$user['id']);}
elseif($role==='admin')$stmt=$conn->prepare("SELECT r.*,u.full_name requester_name FROM reservations r JOIN users u ON r.requester_id=u.id ORDER BY r.is_emergency DESC,r.created_at DESC");
elseif($role==='secretary')$stmt=$conn->prepare("SELECT r.*,u.full_name requester_name FROM reservations r JOIN users u ON r.requester_id=u.id WHERE r.status<>'Pending Admin Review' ORDER BY r.is_emergency DESC,r.created_at DESC");
else $stmt=$conn->prepare("SELECT r.*,u.full_name requester_name,v.vehicle_name,d.full_name driver_name FROM reservations r JOIN users u ON r.requester_id=u.id LEFT JOIN vehicles v ON r.vehicle_id=v.id LEFT JOIN drivers d ON r.driver_id=d.id ORDER BY r.is_emergency DESC,r.created_at DESC");
$stmt->execute();$rows=$stmt->get_result();
$vehicles=$conn->query("SELECT * FROM vehicles WHERE status IN ('Available','In Use') ORDER BY vehicle_name");$drivers=$conn->query("SELECT * FROM drivers WHERE status IN ('Available','Assigned') ORDER BY full_name");
$draft=($_SERVER['REQUEST_METHOD']==='POST' && $error && ($_POST['action']??'')==='create')?$_POST:[];
