ied']?'Verified by staff':'Pending staff verification'?></small><?php endif;?><input type="file" name="valid_id" accept="image/jpeg,image/png,application/pdf"<?=empty($identity['valid_id_path'])?' required':''?>></label><label>Valid ID back (JPG, PNG, or PDF; max 5 MB)<?php if(!empty($identity['valid_id_back_path'])):?><small class="doc-state"><a class="text-link" href="view-requester-document.php?user=<?=(int)$user['id']?>&amp;type=valid_id_back" target="_blank" rel="noopener">View uploaded back</a></small><?php endif;?><input type="file" name="valid_id_back" accept="image/jpeg,image/png,application/pdf"<?=empty($identity['valid_id_back_path'])?" required":""?>></label><label>Birth certificate (optional; if applicable)<?php if(!empty($identity['birth_certificate_path'])):?><small class="doc-state"><a class="text-link" href="view-requester-document.php?user=<?=(int)$user['id']?>&amp;type=birth_certificate" target="_blank" rel="noopener">View uploaded document</a></small><?php endif;?><input type="file" name="birth_certificate" accept="image/jpeg,image/png,application/pdf"></label><label>Death certificate (optional; if applicable)<?php if(!empty($identity['death_certificate_path'])):?><small class="doc-state"><a class="text-link" href="view-requester-document.php?user=<?=(int)$user['id']?>&amp;type=death_certificate" target="_blank" rel="noopener">View uploaded document</a></small><?php endif;?><input type="file" name="death_certificate" accept="image/jpeg,image/png,application/pdf"></label><label class="span-2 check-label"><input type="checkbox" name="is_emergency" value="1"<?=!empty($draft['is_emergency'])?' checked':''?>> Mark as urgent / emergency request</label><div class="span-2"><button class="btn primary" type="submit">Submit request →</button></div></form></section><?php endif;?>
