requesterHistoryRows && $requesterHistoryRows->num_rows):?><div class="requester-history"><b>Previous requests</b><ul><?php while($historyItem=$requesterHistoryRows->fetch_assoc()):?><li><a href="reservations.php?id=<?=(int)$historyItem['id']?>"><?=h($historyItem['reference_no'])?></a> · <?=h($historyItem['status'])?> · <?=h(date('M d, Y',strtotime($historyItem['created_at'])))?></li><?php endwhile;?></ul></div><?php endif;?></section><?php endif;?>
<?php if($role==='admin' && $detail['status']==='Pending Admin Review'):?><hr><h3>Administrative review</h3><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="admin_review"><input type="hidden" name="id" value="<?=$detail['id']?>"><input name="note" placeholder="Review note (optional)"><?php if(empty($detail['id_verified'])):?><label class="check-label"><input type="checkbox" name="verify_requester_id" value="1"> I checked both sides of the valid ID and confirmed the requester</label><?php endif;?><button class="btn primary" name="decision" value="forward">Forward to Secretary</button><button class="btn danger" name="decision" value="reject">Reject</button></form><?php endif;?>
<?php if($role==='secretary' && $detail['status']==='Pending Secretary Approval'):?><hr><h3>Secretary decision</h3><p class="muted">This records the decision for the configured approval workflow. Confirm actual Mayor approval requirements with the LGU.</p><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="secretary_review"><input type="hidden" name="id" value="<?=$detail['id']?>"><input name="note" placeholder="Decision note (optional)"><button class="btn primary" name="decision" value="approve">Approve</button><button class="btn danger" name="decision" value="reject">Reject</button></form><?php endif;?>
<?php if($role==='gso' && $detail['status']==='Approved'):?><hr><h3>Assign vehicle & driver</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="assign"><input type="hidden" name="id" value="<?=$detail['id']?>"><label>Vehicle<select name="vehicle_id" required><?php while($v=$vehicles->fetch_assoc()):?><option value="<?=$v['id']?>"><?=h($v['vehicle_name'].' · '.$v['plate_number'].' · '.$v['status'])?></option><?php endwhile;?></select></label><label>Driver<select name="driver_id" required><?php while($d=$drivers->fetch_assoc()):?><option value="<?=$d['id']?>"><?=h($d['full_name'].' · '.$d['status'])?></option><?php endwhile;?></select></label><div><button class="btn primary">Confirm assignment</button></div></form><?php endif;?>
<?php if($role==='gso' && $detail['status']==='Assigned'):?><hr><h3>Dispatch record</h3><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="dispatch"><input type="hidden" name="id" value="<?=$detail['id']?>"><label>Odometer out<input type="number" name="odometer_out" min="0" step=".1" required></label><label>Fuel level<input name="fuel_out" placeholder="e.g. ¾ tank" required></label><button class="btn primary">Record dispatch</button></form><?php endif;?>
<?php if($role==='gso' && $detail['status']==='Dispatched'):?><hr><h3>Vehicle return</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="return"><input type="hidden" name="id" value="<?=$detail['id']?>"><label>Odometer in<input type="number" name="odometer_in" min="0" step=".1" required></label><label>Fuel level on return<input name="fuel_in" required></label><label class="span-2">Vehicle condition<input name="return_condition" placeholder="e.g. Good condition / note damage" required></label><div><button class="btn primary">Complete return</button></div></form><?php endif;?>
<?php if($role==='requester' && $detail['status']==='Pending Admin Review'):?><form method="post" class="detail-actions" onsubmit="return confirm('Cancel this reservation request?')"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$detail['id']?>"><button class="btn danger">Cancel request</button></form><?php endif;?>
<?php if($detail['admin_note']):?><p class="note-line"><b>Admin note:</b> <?=h($detail['admin_note'])?></p><?php endif;?><?php if($detail['secretary_note']):?><p class="note-line"><b>Secretary note:</b> <?=h($detail['secretary_note'])?></p><?php endif;?></section><?php endif;?>
<section class="content-card"><div class="section-head"><div><h2>All requests</h2><p>Choose a reference number to open details and available actions.</p></div></div><div class="table-wrap"><table><thead><tr><th>REFERENCE</th><?php if($role!=='requester'):?><th>REQUESTER</th><?php endif;?><th>DESTINATION</th><th>DEPARTURE</th><th>STATUS</th><th>PRIORITY</th><th></th></tr></thead><tbody><?php if(!$rows->num_rows):?><tr><td colspan="7" class="empty">No reservations found.</td></tr><?php endif;?><?php while($r=$rows->fetch_assoc()):?><tr><td><b class="ref"><?=h($r['reference_no'])?></b><small class="cell-sub"><?=h($r['vehicle_type'])?></small></td><?php if($role!=='requester'):?><td><?=h($r['requester_name'])?></td><?php endif;?><td><?=h($r['destination'])?><small class="cell-sub"><?=h($r['purpose'])?></small></td><td><?=h(date('M d, Y',strtotime($r['departure_at'])))?><small class="cell-sub"><?=h(date('g:i A',strtotime($r['departure_at'])))?></small></td><td><span class="status <?=strtolower(str_replace(' ','-',$r['status']))?>"><?=h($r['status'])?></span></td><td><?=$r['is_emergency']?'<span class="status emergency">Urgent</span>':'<span class="muted">Normal</span>'?></td><td><a class="icon-link" href="reservations.php?id=<?=(int)$r['id']?>">↗</a></td></tr><?php endwhile;?></tbody></table></div></section><footer>© <?=date('Y')?> LGU Inabanga, Bohol · Vehicle Reservation & Dispatch Tracking</footer></main></div></body></html>
